shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  darkWalnut : vec3<f32>,
  warmWalnut : vec3<f32>,
  satinLift : f32,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let grainLine = sin(((in.vUv.x * 92.0) + (sin((in.vUv.y * 11.0)) * 2.2)));
  let grain = ((grainLine * 0.5) + 0.5);
  let endGrain = (sin(((in.vUv.x + in.vUv.y) * 17.0)) * 0.04);
  let holeUV = (in.vUv - vec2<f32>(0.5, 0.5));
  let carved = (smoothstep(0.34, 0.04, length(holeUV)) * 0.18);
  let body = mix(u.darkWalnut.rgb, u.warmWalnut.rgb, ((grain * 0.52) + endGrain));
  return vec4<f32>(((body * (1.0 - carved)) + vec3<f32>(u.satinLift, u.satinLift, u.satinLift)), 1.0);
}

shaders.vertex:
#version 300 es
in vec3 position;
in vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 darkWalnut;
uniform vec3 warmWalnut;
uniform float satinLift;
out vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 darkWalnut;
uniform vec3 warmWalnut;
uniform float satinLift;
in vec2 vUv;
out vec4 fragColor;

void main() {
  float grainLine = sin(((vUv.x * 92.0) + (sin((vUv.y * 11.0)) * 2.2)));
  float grain = ((grainLine * 0.5) + 0.5);
  float endGrain = (sin(((vUv.x + vUv.y) * 17.0)) * 0.04);
  vec2 holeUV = (vUv - vec2(0.5, 0.5));
  float carved = (smoothstep(0.34, 0.04, length(holeUV)) * 0.18);
  vec3 body = mix(darkWalnut.rgb, warmWalnut.rgb, ((grain * 0.52) + endGrain));
  fragColor = vec4(((body * (1.0 - carved)) + vec3(satinLift, satinLift, satinLift)), 1.0);
}
